import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import { get_material_unit } from "@/mixins/GetMaterialUnit.js";
import { get_units_items } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import UnitDialog from "./UnitDialog.vue";
import DeleteUnitDialog from "./DeleteUnitDialog.vue";
import UnitItems from "./UnitItems.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  name: "Units",
  components: {
    UnitDialog,
    DeleteUnitDialog,
    UnitItems,
    SnackBar
  },
  mixins: [get_material_unit],
  data() {
    return {
      unitmaterials: [],
      searchUnit: "",
      windowHeight: 0,
      unitDialog: false,
      deleteUnitDialog: false,
      ItemDialog: false,
      editingUnit: null,
      unitToDelete: null,
      selectedUnitItems: [],
      tableLoading: false,
      SnackBarComponent: {},
      unitHeaders: [{
        title: "Full Name",
        value: "unit_name",
        align: "start",
        sortable: true
      }, {
        title: "Created By",
        value: "unit_created_by",
        align: "center",
        sortable: true
      }, {
        title: "",
        value: "actions",
        align: "end",
        sortable: false
      }]
    };
  },
  computed: {
    filteredUnits() {
      if (!this.searchUnit) return this.unitmaterials;
      return this.unitmaterials.filter(u => u.unit_name.toLowerCase().includes(this.searchUnit.toLowerCase()) || u.short_name.toLowerCase().includes(this.searchUnit.toLowerCase()));
    }
  },
  async mounted() {
    this.tableLoading = true;
    this.windowHeight = window.innerHeight - 280;
    await this.get_material_unit();
    this.tableLoading = false;
  },
  methods: {
    onRowClick(event, row) {
      const unit = row.item;
      console.log("Clicked row:", unit);
      this.openUnitItems(unit);
    },
    async openUnitItems(unit) {
      this.ItemDialog = true;
      this.tableLoading = true;
      this.selectedUnitItems = [];
      try {
        const result = await API.graphql(graphqlOperation(get_units_items, {
          input: {
            unit_id: unit.unit_id
          }
        }));
        const res = JSON.parse(result.data.get_units_items);
        this.selectedUnitItems = res.Status === "SUCCESS" ? res.data : [];
      } catch (err) {
        this.error_info("Failed to load unit items");
      } finally {
        this.tableLoading = false;
      }
    },
    addUnit() {
      this.editingUnit = null;
      this.unitDialog = true;
    },
    editUnit(unit) {
      this.editingUnit = unit;
      this.unitDialog = true;
    },
    deleteUnit(unit) {
      this.unitToDelete = unit;
      this.deleteUnitDialog = true;
    },
    success_info(msg) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: msg,
        timeout: 4000,
        Top: true
      };
      this.get_material_unit();
      this.unitDialog = false;
      this.deleteUnitDialog = false;
    },
    error_info(msg) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: msg,
        timeout: 4000,
        Top: true
      };
    }
  }
};
